// Verificación del Webhook de Meta (hub.challenge)
const query = $input.first().json.query || {};
const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];

// El verify_token se toma de las variables de entorno o credencial de n8n
const VERIFY_TOKEN = $env['META_VERIFY_TOKEN'] || 'asygnuz_ig_webhook_secret_2026';

if (mode === 'subscribe' && token === VERIFY_TOKEN) {
  return [{ json: { autorizado: true, challenge: String(challenge) } }];
} else {
  return [{ json: { autorizado: false } }];
}

// Validación de firma criptográfica X-Hub-Signature-256
const crypto = require('crypto');

const headers = $input.first().json.headers || {};
const rawBody = $input.first().json.rawBody || JSON.stringify($input.first().json.body || {});
const signatureHeader = headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'] || '';

// El App Secret de Instagram configurado en n8n
const APP_SECRET = $env['META_INSTAGRAM_APP_SECRET'] || '';

let firmaValida = true;
if (APP_SECRET && signatureHeader) {
  const hmac = crypto.createHmac('sha256', APP_SECRET);
  hmac.update(rawBody, 'utf8');
  const expected = 'sha256=' + hmac.digest('hex');
  firmaValida = crypto.timingSafeEqual(Buffer.from(signatureHeader), Buffer.from(expected));
}

return [{
  json: {
    firmaValida,
    body: typeof $input.first().json.body === 'object' ? $input.first().json.body : JSON.parse(rawBody || '{}')
  }
}];

// Normalización y enrutamiento de eventos entrantes de Instagram
const body = $input.first().json.body || {};
const entries = body.entry || [];

const eventosProcesados = [];

for (const entry of entries) {
  const igAccountId = entry.id;
  const time = entry.time;

  // 1. Mensajes Directos (DMs)
  if (entry.messaging && Array.isArray(entry.messaging)) {
    for (const msg of entry.messaging) {
      // Descartar ecos generados por la propia cuenta
      if (msg.message && msg.message.is_echo) continue;
      if (msg.sender && msg.sender.id === igAccountId) continue;

      eventosProcesados.push({
        tipo: 'message',
        ig_cuenta_id: igAccountId,
        ig_usuario_id: msg.sender?.id,
        meta_evento_id: msg.message?.mid || `msg_${time}_${msg.sender?.id}`,
        texto: msg.message?.text || '',
        timestamp: new Date(msg.timestamp || time || Date.now()).toISOString(),
        crudo: msg
      });
    }
  }

  // 2. Comentarios en Publicaciones
  if (entry.changes && Array.isArray(entry.changes)) {
    for (const change of entry.changes) {
      if (change.field === 'comments') {
        const val = change.value || {};
        // Ignorar comentarios de la propia cuenta
        if (val.from && val.from.id === igAccountId) continue;

        eventosProcesados.push({
          tipo: 'comment',
          ig_cuenta_id: igAccountId,
          ig_usuario_id: val.from?.id,
          ig_usuario_nombre: val.from?.username,
          meta_evento_id: val.id || `cmt_${time}_${val.from?.id}`,
          comment_id: val.id,
          media_id: val.media?.id,
          texto: val.text || '',
          timestamp: new Date(Date.now()).toISOString(),
          crudo: change
        });
      }
    }
  }
}

return eventosProcesados.map(e => ({ json: e }));
